-- Podrazumevano NISTA nije vidljivo. Svaka vidljivost je izricita.
-- Ovo je jedino mesto gde se privatnost stvarno sprovodi ΓÇö ekran nije zastita.

alter table public.needs                         enable row level security;
alter table public.need_sensitive                enable row level security;
alter table public.need_selections               enable row level security;
alter table public.marketplace_responses         enable row level security;
alter table public.marketplace_response_versions enable row level security;
alter table public.agreements                    enable row level security;
alter table public.agreement_versions            enable row level security;
alter table public.agreement_messages            enable row level security;
alter table public.agreement_execution           enable row level security;
alter table public.access_grants                 enable row level security;
alter table public.ai_conversations              enable row level security;
alter table public.ai_structured_facts           enable row level security;
alter table public.ai_action_proposals           enable row level security;

create policy needs_owner_all on public.needs
  for all to authenticated
  using (requester_account_id = auth.uid())
  with check (requester_account_id = auth.uid());

create policy needs_published_read on public.needs
  for select to authenticated
  using (status = 'PUBLISHED');

create policy need_sensitive_owner on public.need_sensitive
  for all to authenticated
  using (exists (select 1 from public.needs n where n.id = need_id and n.requester_account_id = auth.uid()))
  with check (exists (select 1 from public.needs n where n.id = need_id and n.requester_account_id = auth.uid()));

create policy need_sensitive_granted_read on public.need_sensitive
  for select to authenticated
  using (exists (
    select 1 from public.agreements a
      join public.access_grants g on g.agreement_id = a.id
     where a.need_id = need_sensitive.need_id
       and g.channel = 'EXACT_LOCATION'
       and g.status = 'GRANTED'
       and g.granted_to_account_id = auth.uid()));

create policy responses_worker_all on public.marketplace_responses
  for all to authenticated
  using (worker_account_id = auth.uid())
  with check (worker_account_id = auth.uid());

create policy responses_requester_read on public.marketplace_responses
  for select to authenticated
  using (status <> 'DRAFT'
     and exists (select 1 from public.needs n where n.id = need_id and n.requester_account_id = auth.uid()));

create policy response_versions_read on public.marketplace_response_versions
  for select to authenticated
  using (exists (
    select 1 from public.marketplace_responses r
     where r.id = response_id
       and (r.worker_account_id = auth.uid()
            or (r.status <> 'DRAFT'
                and exists (select 1 from public.needs n where n.id = r.need_id and n.requester_account_id = auth.uid())))));

create policy selections_requester on public.need_selections
  for select to authenticated
  using (selected_by_account_id = auth.uid());

create policy agreements_parties_read on public.agreements
  for select to authenticated
  using (requester_account_id = auth.uid() or worker_account_id = auth.uid());

create policy agreement_versions_read on public.agreement_versions
  for select to authenticated
  using (exists (select 1 from public.agreements a
                  where a.id = agreement_id
                    and (a.requester_account_id = auth.uid() or a.worker_account_id = auth.uid())));

create policy agreement_execution_read on public.agreement_execution
  for select to authenticated
  using (exists (select 1 from public.agreements a
                  where a.id = agreement_id
                    and (a.requester_account_id = auth.uid() or a.worker_account_id = auth.uid())));

create policy agreement_messages_read on public.agreement_messages
  for select to authenticated
  using (exists (select 1 from public.agreements a
                  where a.id = agreement_id
                    and (a.requester_account_id = auth.uid() or a.worker_account_id = auth.uid())));

create policy agreement_messages_send on public.agreement_messages
  for insert to authenticated
  with check (sender_account_id = auth.uid()
    and exists (select 1 from public.agreements a
                 where a.id = agreement_id
                   and a.status in ('CONFIRMED','SUPERSEDED')
                   and (a.requester_account_id = auth.uid() or a.worker_account_id = auth.uid())));

create policy access_grants_read on public.access_grants
  for select to authenticated
  using (granted_by_account_id = auth.uid() or granted_to_account_id = auth.uid());

create policy access_grants_grant on public.access_grants
  for insert to authenticated
  with check (granted_by_account_id = auth.uid()
    and exists (select 1 from public.agreements a
                 where a.id = agreement_id
                   and (a.requester_account_id = auth.uid() or a.worker_account_id = auth.uid())));

create policy access_grants_revoke on public.access_grants
  for update to authenticated
  using (granted_by_account_id = auth.uid())
  with check (granted_by_account_id = auth.uid());

create policy ai_conversations_own on public.ai_conversations
  for all to authenticated
  using (account_id = auth.uid()) with check (account_id = auth.uid());

create policy ai_facts_own on public.ai_structured_facts
  for all to authenticated
  using (account_id = auth.uid()) with check (account_id = auth.uid());

create policy ai_proposals_own on public.ai_action_proposals
  for all to authenticated
  using (account_id = auth.uid()) with check (account_id = auth.uid());

comment on policy agreement_messages_read on public.agreement_messages is
  'M04: chat radi NEZAVISNO od dozvola za privatne podatke. Uslov je clanstvo u Dogovoru, ne postojanje granta.';
comment on policy access_grants_grant on public.access_grants is
  'Dozvolu daje SAMO onaj ciji je podatak. Niko ne moze da podeli tudji broj.';

-- M02: ATOMSKI TACAN IZBOR. Jedina funkcija koja sme da napravi Dogovor.
-- Odbija se ako se promenila revizija Potrebe, verzija Prijave ili hash uslova.
-- Idempotentno po clientRequestId.

create or replace function public.fn_need_covered_slots(p_need_id uuid)
returns integer language sql stable security definer
set search_path = public, pg_temp
as $fn$
  select coalesce(sum(r.covered_slots), 0)::integer
    from public.agreements a
    join public.marketplace_responses r on r.id = a.selected_response_id
   where a.need_id = p_need_id
     and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED');
$fn$;

revoke all on function public.fn_need_covered_slots(uuid) from public, anon;

create or replace function public.rpc_select_response(
  p_need_id uuid, p_need_revision integer, p_response_id uuid,
  p_response_version integer, p_content_hash text, p_client_request_id text
) returns uuid language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare
  uid uuid := auth.uid();
  v_need public.needs%rowtype;
  v_resp public.marketplace_responses%rowtype;
  v_ver public.marketplace_response_versions%rowtype;
  v_selection_id uuid; v_agreement_id uuid; v_covered integer; v_terms jsonb;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;

  select a.id into v_agreement_id
    from public.need_selections s
    join public.agreements a on a.selection_id = s.id
   where s.need_id = p_need_id and s.client_request_id = p_client_request_id;
  if found then return v_agreement_id; end if;

  select * into v_need from public.needs where id = p_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_need.requester_account_id <> uid then raise exception 'NOT_REQUESTER' using errcode = '42501'; end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then
    raise exception 'NEED_NOT_OPEN' using errcode = 'P0001', detail = v_need.status; end if;

  if v_need.revision <> p_need_revision then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'need_revision',
      hint = 'Potreba je izmenjena. Pogledajte prijave ponovo.'; end if;

  select * into v_resp from public.marketplace_responses where id = p_response_id for update;
  if not found then raise exception 'RESPONSE_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_resp.need_id <> p_need_id then raise exception 'RESPONSE_NEED_MISMATCH' using errcode = 'P0001'; end if;
  if v_resp.status not in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED') then
    raise exception 'RESPONSE_NOT_SELECTABLE' using errcode = 'P0001', detail = v_resp.status; end if;

  if v_resp.current_version <> p_response_version then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'response_version',
      hint = 'Uskocer je izmenio prijavu. Proverite je ponovo.'; end if;

  select * into v_ver from public.marketplace_response_versions
   where response_id = p_response_id and version = p_response_version;
  if not found then raise exception 'RESPONSE_VERSION_NOT_FOUND' using errcode = 'P0002'; end if;

  if v_ver.content_hash <> p_content_hash then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'content_hash',
      hint = 'Uslovi prijave su izmenjeni.'; end if;

  if v_ver.need_revision <> v_need.revision then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'response_need_revision'; end if;

  v_covered := public.fn_need_covered_slots(p_need_id);
  if v_covered + v_resp.covered_slots > v_need.required_slots then
    raise exception 'OVERFILL' using errcode = 'P0001',
      hint = 'Ta prijava pokriva vise mesta nego sto je preostalo.'; end if;

  insert into public.need_selections
    (need_id, need_revision, selected_by_account_id, client_request_id, covered_slots)
  values (p_need_id, v_need.revision, uid, p_client_request_id, v_resp.covered_slots)
  returning id into v_selection_id;

  v_terms := jsonb_build_object(
    'price_rsd', v_ver.price_rsd, 'covered_slots', v_ver.covered_slots,
    'proposed_start_at', v_ver.proposed_start_at, 'proposed_end_at', v_ver.proposed_end_at,
    'scope_note', v_ver.scope_note, 'need_revision', v_need.revision,
    'response_version', v_ver.version);

  insert into public.agreements
    (need_id, selection_id, selected_response_id, requester_account_id, requester_profile_id,
     worker_account_id, worker_profile_id, current_version, status)
  values (p_need_id, v_selection_id, p_response_id, v_need.requester_account_id, v_need.requester_profile_id,
     v_resp.worker_account_id, v_resp.worker_profile_id, 1, 'CONFIRMED')
  returning id into v_agreement_id;

  insert into public.agreement_versions
    (agreement_id, version, status, terms, content_hash, created_by_account_id)
  values (v_agreement_id, 1, 'CONFIRMED', v_terms, v_ver.content_hash, uid);

  insert into public.agreement_execution (agreement_id, agreement_version, mode, state)
  values (v_agreement_id, 1,
    case when v_need.schedule_kind = 'REMOTE_ANYTIME' then 'REMOTE' else 'PHYSICAL' end, 'CONFIRMED');

  update public.marketplace_responses
     set status = 'SELECTED', selected_at = statement_timestamp(), updated_at = statement_timestamp()
   where id = p_response_id;

  update public.needs
     set status = case when v_covered + v_resp.covered_slots >= v_need.required_slots
                       then 'ACTIVE' else 'SELECTION' end,
         updated_at = statement_timestamp()
   where id = p_need_id;

  return v_agreement_id;
end;
$fn$;

revoke all on function public.rpc_select_response(uuid,integer,uuid,integer,text,text) from public, anon;
grant execute on function public.rpc_select_response(uuid,integer,uuid,integer,text,text) to authenticated;

comment on function public.rpc_select_response is
  'M02: atomski izbor. Vezuje tacnu reviziju Potrebe, verziju i hash Prijave. Idempotentno po clientRequestId. Nema trece potvrde.';

-- M05 prihvacena izmena ODMAH aktivira v+1, stara ostaje nepromenljiva
-- M06 otkazivanje je JEDNOSTRANO i oslobadja SAMO tu alokaciju
-- M07 zavrsetak otvara serverski prozor od 48h; sat je serverski

create or replace function public.fn_is_party(p_agreement_id uuid, p_uid uuid)
returns boolean language sql stable security definer
set search_path = public, pg_temp
as $fn$
  select exists (select 1 from public.agreements a
    where a.id = p_agreement_id and (a.requester_account_id = p_uid or a.worker_account_id = p_uid));
$fn$;
revoke all on function public.fn_is_party(uuid, uuid) from public, anon;

create or replace function public.rpc_propose_agreement_change(
  p_agreement_id uuid, p_expected_version integer, p_terms jsonb,
  p_content_hash text, p_client_request_id text
) returns integer language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_agr public.agreements%rowtype; v_new_ver integer;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  select * into v_agr from public.agreements where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if not public.fn_is_party(p_agreement_id, uid) then raise exception 'NOT_PARTY' using errcode = '42501'; end if;
  if v_agr.status <> 'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_ACTIVE' using errcode = 'P0001', detail = v_agr.status; end if;
  if v_agr.current_version <> p_expected_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001',
      hint = 'Dogovor je u medjuvremenu promenjen. Osvezite pa pokusajte ponovo.'; end if;

  select version into v_new_ver from public.agreement_versions
   where agreement_id = p_agreement_id and terms->>'client_request_id' = p_client_request_id;
  if found then return v_new_ver; end if;

  v_new_ver := v_agr.current_version + 1;
  insert into public.agreement_versions
    (agreement_id, version, status, terms, content_hash, supersedes_version, created_by_account_id)
  values (p_agreement_id, v_new_ver, 'CONFIRMED',
    p_terms || jsonb_build_object('client_request_id', p_client_request_id),
    p_content_hash, v_agr.current_version, uid);

  update public.agreement_versions set status = 'SUPERSEDED'
   where agreement_id = p_agreement_id and version = v_agr.current_version;
  update public.agreements set current_version = v_new_ver, updated_at = statement_timestamp()
   where id = p_agreement_id;
  return v_new_ver;
end;
$fn$;
revoke all on function public.rpc_propose_agreement_change(uuid,integer,jsonb,text,text) from public, anon;
grant execute on function public.rpc_propose_agreement_change(uuid,integer,jsonb,text,text) to authenticated;

create or replace function public.rpc_cancel_agreement(p_agreement_id uuid, p_reason text)
returns void language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_agr public.agreements%rowtype;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'REASON_REQUIRED' using errcode = 'P0001'; end if;
  select * into v_agr from public.agreements where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if not public.fn_is_party(p_agreement_id, uid) then raise exception 'NOT_PARTY' using errcode = '42501'; end if;
  if v_agr.status = 'COMPLETED' then raise exception 'ALREADY_COMPLETED' using errcode = 'P0001'; end if;

  update public.agreements set status = 'CANCELLED', updated_at = statement_timestamp() where id = p_agreement_id;
  update public.agreement_execution set state = 'CANCELLED', updated_at = statement_timestamp()
   where agreement_id = p_agreement_id;

  update public.needs n
     set status = case when n.status = 'ACTIVE' then 'SELECTION' else n.status end,
         updated_at = statement_timestamp()
   where n.id = v_agr.need_id and public.fn_need_covered_slots(n.id) < n.required_slots;
end;
$fn$;
revoke all on function public.rpc_cancel_agreement(uuid,text) from public, anon;
grant execute on function public.rpc_cancel_agreement(uuid,text) to authenticated;

create or replace function public.rpc_mark_work_done(p_agreement_id uuid)
returns timestamptz language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_agr public.agreements%rowtype; v_dl timestamptz;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  select * into v_agr from public.agreements where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_agr.worker_account_id <> uid then raise exception 'NOT_WORKER' using errcode = '42501'; end if;
  if v_agr.status <> 'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_ACTIVE' using errcode = 'P0001', detail = v_agr.status; end if;

  v_dl := statement_timestamp() + interval '48 hours';
  update public.agreement_execution
     set state = 'AWAITING_REQUESTER', worker_marked_done_at = statement_timestamp(),
         requester_deadline_at = v_dl, updated_at = statement_timestamp()
   where agreement_id = p_agreement_id;
  return v_dl;
end;
$fn$;
revoke all on function public.rpc_mark_work_done(uuid) from public, anon;
grant execute on function public.rpc_mark_work_done(uuid) to authenticated;

create or replace function public.rpc_confirm_completion(p_agreement_id uuid)
returns void language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_agr public.agreements%rowtype;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  select * into v_agr from public.agreements where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_agr.requester_account_id <> uid then raise exception 'NOT_REQUESTER' using errcode = '42501'; end if;
  if v_agr.status = 'COMPLETED' then raise exception 'ALREADY_COMPLETED' using errcode = 'P0001'; end if;

  update public.agreements set status = 'COMPLETED', updated_at = statement_timestamp() where id = p_agreement_id;
  update public.agreement_execution
     set state = 'COMPLETED', completed_at = statement_timestamp(),
         requester_deadline_at = null, updated_at = statement_timestamp()
   where agreement_id = p_agreement_id;
end;
$fn$;
revoke all on function public.rpc_confirm_completion(uuid) from public, anon;
grant execute on function public.rpc_confirm_completion(uuid) to authenticated;

create or replace function public.rpc_report_problem(p_agreement_id uuid, p_narrative text)
returns void language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_rows integer;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if coalesce(btrim(p_narrative), '') = '' then raise exception 'NARRATIVE_REQUIRED' using errcode = 'P0001'; end if;
  if not public.fn_is_party(p_agreement_id, uid) then raise exception 'NOT_PARTY' using errcode = '42501'; end if;

  update public.agreement_execution
     set problem_opened_at = coalesce(problem_opened_at, statement_timestamp()),
         updated_at = statement_timestamp()
   where agreement_id = p_agreement_id and state <> 'COMPLETED';
  get diagnostics v_rows = row_count;
  if v_rows = 0 then raise exception 'NOT_OPEN' using errcode = 'P0001'; end if;
end;
$fn$;
revoke all on function public.rpc_report_problem(uuid,text) from public, anon;
grant execute on function public.rpc_report_problem(uuid,text) to authenticated;

create or replace function public.rpc_tick_auto_completion()
returns integer language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare v_count integer := 0;
begin
  with due as (
    select e.agreement_id from public.agreement_execution e
     where e.state = 'AWAITING_REQUESTER' and e.problem_opened_at is null
       and e.requester_deadline_at is not null
       and e.requester_deadline_at <= statement_timestamp()
  ), zatvoreni as (
    update public.agreement_execution e
       set state = 'COMPLETED', completed_at = statement_timestamp(),
           requester_deadline_at = null, updated_at = statement_timestamp()
      from due where e.agreement_id = due.agreement_id
    returning e.agreement_id
  )
  update public.agreements a set status = 'COMPLETED', updated_at = statement_timestamp()
    from zatvoreni z where a.id = z.agreement_id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$fn$;

revoke all on function public.rpc_tick_auto_completion() from public, anon, authenticated;

comment on function public.rpc_tick_auto_completion is
  'M07: serverski tick. Namerno bez granta korisnicima ΓÇö poziva ga scheduler servisnim kljucem, ne otvoren ekran.';

-- R02: AI_PROPOSED -> HUMAN_CONFIRMED -> CANONICAL_SAVED
-- AI ne moze ni da pokusa da upise CONFIRMED, ni da objavi nepotvrdjeno.

create or replace function public.rpc_ai_open_conversation(p_purpose text)
returns uuid language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_id uuid;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if p_purpose not in ('NEED_INTAKE','APPLICATION','PROFILE') then
    raise exception 'BAD_PURPOSE' using errcode = 'P0001'; end if;
  insert into public.ai_conversations (account_id, purpose) values (uid, p_purpose) returning id into v_id;
  return v_id;
end;
$fn$;
revoke all on function public.rpc_ai_open_conversation(text) from public, anon;
grant execute on function public.rpc_ai_open_conversation(text) to authenticated;

create or replace function public.rpc_ai_propose_fact(
  p_conversation_id uuid, p_fact_key text, p_fact_value jsonb,
  p_source text, p_scope text, p_confidence numeric default null, p_evidence text default null
) returns uuid language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_conv public.ai_conversations%rowtype; v_old uuid; v_new uuid;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  select * into v_conv from public.ai_conversations where id = p_conversation_id for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_conv.account_id <> uid then raise exception 'NOT_OWNER' using errcode = '42501'; end if;
  if v_conv.status <> 'OPEN' then raise exception 'CONVERSATION_CLOSED' using errcode = 'P0001'; end if;
  if p_source not in ('EXPLICIT_USER_ANSWER','CONFIRMED_PROFILE','AI_INFERENCE','SYSTEM_DERIVED') then
    raise exception 'BAD_SOURCE' using errcode = 'P0001'; end if;

  if p_source = 'AI_INFERENCE' and coalesce(btrim(p_evidence), '') = '' then
    raise exception 'EVIDENCE_REQUIRED' using errcode = 'P0001',
      hint = 'AI zakljucak mora da nosi citat iz razgovora.'; end if;

  select id into v_old from public.ai_structured_facts
   where conversation_id = p_conversation_id and fact_key = p_fact_key and superseded_at is null;

  insert into public.ai_structured_facts
    (account_id, conversation_id, subject_need_id, fact_key, fact_value,
     status, source, scope, confidence, evidence_excerpt)
  values (uid, p_conversation_id, v_conv.bound_need_id, p_fact_key, p_fact_value,
     'NEEDS_CONFIRMATION', p_source, p_scope, p_confidence, p_evidence)
  returning id into v_new;

  if v_old is not null then
    update public.ai_structured_facts
       set superseded_at = statement_timestamp(), superseded_by = v_new where id = v_old;
  end if;
  return v_new;
end;
$fn$;
revoke all on function public.rpc_ai_propose_fact(uuid,text,jsonb,text,text,numeric,text) from public, anon;
grant execute on function public.rpc_ai_propose_fact(uuid,text,jsonb,text,text,numeric,text) to authenticated;

create or replace function public.rpc_ai_confirm_fact(p_fact_id uuid)
returns uuid language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare uid uuid := auth.uid(); v_fact public.ai_structured_facts%rowtype;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  select * into v_fact from public.ai_structured_facts where id = p_fact_id for update;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_fact.account_id <> uid then raise exception 'NOT_OWNER' using errcode = '42501'; end if;
  if v_fact.superseded_at is not null then
    raise exception 'SUPERSEDED' using errcode = 'P0001',
      hint = 'Taj podatak je u medjuvremenu izmenjen.'; end if;

  update public.ai_structured_facts
     set status = 'CONFIRMED', source = 'EXPLICIT_USER_ANSWER',
         confirmed_by_user_id = uid, confirmed_at = statement_timestamp()
   where id = p_fact_id;
  return p_fact_id;
end;
$fn$;
revoke all on function public.rpc_ai_confirm_fact(uuid) from public, anon;
grant execute on function public.rpc_ai_confirm_fact(uuid) to authenticated;

create or replace function public.rpc_ai_publish_need(p_conversation_id uuid, p_profile_id uuid)
returns uuid language plpgsql security definer
set search_path = public, pg_temp
as $fn$
declare
  uid uuid := auth.uid(); v_conv public.ai_conversations%rowtype;
  v_need_id uuid; v_missing text; v_val jsonb; k text;
  obavezno text[] := array['naslov','datum','vreme','polaziste','odrediste','osoba'];
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  select * into v_conv from public.ai_conversations where id = p_conversation_id for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_conv.account_id <> uid then raise exception 'NOT_OWNER' using errcode = '42501'; end if;
  if v_conv.bound_need_id is not null then return v_conv.bound_need_id; end if;

  foreach k in array obavezno loop
    select f.fact_value into v_val from public.ai_structured_facts f
     where f.conversation_id = p_conversation_id and f.fact_key = k
       and f.superseded_at is null and f.status = 'CONFIRMED';
    if not found then v_missing := coalesce(v_missing || ', ', '') || k; end if;
  end loop;

  if v_missing is not null then
    raise exception 'UNCONFIRMED_FACTS' using errcode = 'P0001', detail = v_missing,
      hint = 'Sve obavezne podatke morate potvrditi pre objave.'; end if;

  insert into public.needs (
    requester_account_id, requester_profile_id, status, title, description, category,
    approximate_area, schedule_kind, required_slots, mode, revision, published_at)
  select uid, p_profile_id, 'PUBLISHED',
    coalesce(f.fact_value ->> 'naslov', 'Potreba'),
    coalesce(f.fact_value ->> 'opis', ''),
    coalesce(f.fact_value ->> 'kategorija', 'Ostalo'),
    coalesce(f.fact_value ->> 'polaziste', ''),
    'FLEXIBLE',
    least(50, greatest(1,
      coalesce(nullif(regexp_replace(coalesce(f.fact_value ->> 'osoba', ''), '\D', '', 'g'), '')::integer, 1))),
    'OFFERS', 1, statement_timestamp()
  from (
    select jsonb_object_agg(x.fact_key, x.fact_value) as fact_value
      from public.ai_structured_facts x
     where x.conversation_id = p_conversation_id
       and x.superseded_at is null and x.status = 'CONFIRMED'
  ) f
  returning id into v_need_id;

  update public.ai_conversations
     set bound_need_id = v_need_id, status = 'COMPLETED', completed_at = statement_timestamp()
   where id = p_conversation_id;

  update public.ai_structured_facts set subject_need_id = v_need_id
   where conversation_id = p_conversation_id and superseded_at is null;

  return v_need_id;
end;
$fn$;
revoke all on function public.rpc_ai_publish_need(uuid,uuid) from public, anon;
grant execute on function public.rpc_ai_publish_need(uuid,uuid) to authenticated;

comment on function public.rpc_ai_publish_need is
  'R02 CANONICAL_SAVED: objavljuje iz potvrdjenog nacrta, nikad iz istorije poruka.';
